import api from './api';

class AuthService {
    async login(email, password) {
        console.log('[AuthService] login started');
        console.log('[AuthService] Email:', email);
        console.log('[AuthService] Password length:', password.length);
        console.log('[AuthService] API endpoint: /auth/login');

        try {
            console.log('[AuthService] Making API call...');
            const response = await api.post('/auth/login', { email, password });
            console.log('[AuthService] API call completed');
            console.log('[AuthService] Response status:', response.status);
            console.log('[AuthService] Response data:', response.data);
            console.log('[AuthService] Response data keys:', Object.keys(response.data));

            if (response.data.token) {
                console.log('[AuthService] Token received, saving to localStorage');
                localStorage.setItem('token', response.data.token);
                console.log('[AuthService] Token saved');

                console.log('[AuthService] Saving user to localStorage');
                localStorage.setItem('user', JSON.stringify(response.data.user));
                console.log('[AuthService] User saved');
            } else {
                console.log('[AuthService] WARNING: No token in response');
            }

            console.log('[AuthService] Returning response data');
            return response.data;
        } catch (error) {
            console.log('[AuthService] === ERROR in login ===');
            console.log('[AuthService] Error type:', error.constructor.name);
            console.log('[AuthService] Error message:', error.message);
            console.log('[AuthService] Error code:', error.code);
            console.log('[AuthService] Error response:', error.response);

            if (error.response) {
                console.log('[AuthService] Response status:', error.response.status);
                console.log('[AuthService] Response data:', error.response.data);
                console.log('[AuthService] Response headers:', error.response.headers);
            }

            if (error.request) {
                console.log('[AuthService] Request was made but no response received');
                console.log('[AuthService] Request:', error.request);
            }

            if (error.response && error.response.data) {
                console.log('[AuthService] Throwing error.response.data');
                throw error.response.data;
            }

            console.log('[AuthService] Throwing default error object');
            throw { message: 'Ошибка подключения к серверу' };
        }
    }

    async register(userData) {
        try {
            const data = { ...userData };
            const response = await api.post('/auth/register', data);
            if (response.data.token) {
                localStorage.setItem('token', response.data.token);
                localStorage.setItem('user', JSON.stringify(response.data.user));
            }
            return response.data;
        } catch (error) {
            throw error.response?.data || { message: 'Ошибка регистрации' };
        }
    }

    logout() {
        console.log('[AuthService] logout called');
        console.log('[AuthService] Removing token from localStorage');
        localStorage.removeItem('token');

        console.log('[AuthService] Removing user from localStorage');
        localStorage.removeItem('user');

        console.log('[AuthService] Checking if window.location.reload will be called');
        // Убираем перезагрузку, если она есть
        // window.location.href = '/';
        console.log('[AuthService] logout complete - no page reload');
    }

    getCurrentUser() {
        const userStr = localStorage.getItem('user');
        if (userStr) {
            try {
                return JSON.parse(userStr);
            } catch (e) {
                return null;
            }
        }
        return null;
    }

    getToken() {
        return localStorage.getItem('token');
    }

    isAuthenticated() {
        return !!this.getToken();
    }

    async updateProfile(userData) {
        try {
            const response = await api.put('/users/profile', userData);
            if (response.data.user) {
                localStorage.setItem('user', JSON.stringify(response.data.user));
            }
            return response.data;
        } catch (error) {
            throw error.response?.data || { message: 'Ошибка обновления профиля' };
        }
    }

    async changePassword(passwordData) {
        try {
            const response = await api.put('/users/change-password', passwordData);
            return response.data;
        } catch (error) {
            throw error.response?.data || { message: 'Ошибка смены пароля' };
        }
    }

    async deleteAccount() {
        try {
            const response = await api.delete('/users/account');
            this.logout();
            return response.data;
        } catch (error) {
            throw error.response?.data || { message: 'Ошибка удаления аккаунта' };
        }
    }
}

export default new AuthService();
